mapper.select:
SELECT EXISTS (
    SELECT 1 FROM membership_products
    WHERE name = #{name}
    AND id != #{excludedId}
)

SELECT EXISTS (
    SELECT 1
    FROM members
    WHERE id = #{memberId}
      AND status != 'WITHDRAWN'
)

SELECT EXISTS (
    SELECT 1
FROM member_memberships mm
JOIN membership_products mp
    ON mp.id = mm.product_id
WHERE mm.member_id = #{memberId}
 AND mm.status IN (
    'PENDING_PAYMENT',
    'ACTIVE',
    'PAUSED'
)
AND mm.start_date <= #{endDate}
AND mm.end_date >= #{startDate}
AND (
    (
        #{productType} = 'GYM'
        AND mp.product_type IN (
            'GYM',
            'COMBINED'
        )
    )
    OR
    (
        #{productType} = 'PT'
        AND mp.product_type IN (
            'PT',
            'COMBINED'
        )
    )
    OR
    (
        #{productType} = 'COMBINED'
    )
  )
)

mapper.update:
UPDATE member_memberships
SET
    status = #{status},
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{membershipId}
    AND member_id = #{memberId}

UPDATE member_memberships
SET status = 'ACTIVE', updated_at = CURRENT_TIMESTAMP
WHERE id = #{membershipId}
  AND member_id = #{memberId}
  AND status = 'PENDING_PAYMENT'

UPDATE member_memberships
SET status = 'CANCELLED', updated_at = CURRENT_TIMESTAMP
WHERE id = #{membershipId}
  AND member_id = #{memberId}
  AND status IN ('ACTIVE', 'PAUSED')

UPDATE member_memberships
SET status = 'CANCELLED',
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{membershipId}
    AND member_id = #{memberId}
    AND status = 'PENDING_PAYMENT'
